void MOD_mkBramMem::vcd_prims(tVCDDumpType dt, MOD_mkBramMem &backing)
{
  INST_arf.dump_VCD(dt, backing.INST_arf);
  INST_awf.dump_VCD(dt, backing.INST_awf);
  INST_bf.dump_VCD(dt, backing.INST_bf);
  INST_mem.dump_VCD(dt, backing.INST_mem);
  INST_rf.dump_VCD(dt, backing.INST_rf);
  INST_wf.dump_VCD(dt, backing.INST_wf);
}
